const t=raw.content.filter(c=>c.type==="text").map(c=>c.text).join("\n"), cols="ABCDEFGHJ", b={};
for(const line of t.split("\n")){const m=line.match(/^\s*([1-9])\s+([XO.](?:\s+[XO.]){8})\s+[1-9]\s*$/);if(m)m[2].trim().split(/\s+/).forEach((v,i)=>b[cols[i]+m[1]]=v);}
const adj=p=>{const x=cols.indexOf(p[0]),y=+p[1];return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,z])=>a>=0&&a<9&&z>=1&&z<=9).map(([a,z])=>cols[a]+z);};
const seen=new Set(),groups=[],regions=[],counts={X:0,O:0,empty:0};
for(const p of Object.keys(b)){counts[b[p]==="."?"empty":b[p]]++;if(seen.has(p))continue;const v=b[p],q=[p],points=[],libs=new Set(),colors=new Set();seen.add(p);while(q.length){const a=q.pop();points.push(a);for(const n of adj(a)){if(b[n]===v&&!seen.has(n)){seen.add(n);q.push(n);}else if(b[n]!==v){if(b[n]===".")libs.add(n);else colors.add(b[n]);}}}if(v===".")regions.push({points:points.sort(),borders:[...colors]});else groups.push({color:v,points:points.sort(),liberties:[...libs].sort()});}
const area={Black:counts.X,White:counts.O,neutral:0};for(const r of regions)if(r.borders.length===1)area[r.borders[0]==="X"?"Black":"White"]+=r.points.length;else area.neutral+=r.points.length;
