const group=p=>{const v=b[p],q=[p],seen=new Set([p]),libs=new Set();while(q.length){for(const n of adj(q.pop())){if(b[n]==="." )libs.add(n);else if(b[n]===v&&!seen.has(n)){seen.add(n);q.push(n);}}}return {points:[...seen],libs:[...libs]};};
const key=()=>Object.keys(b).sort().map(p=>b[p]).join("");
